/* ============================== SETUP ============================== */

function setup() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  PropertiesService.getScriptProperties().setProperty('SSID', ss.getId());
  Object.keys(SCHEMA).forEach(name => {
    let s = ss.getSheetByName(name);
    if (!s) s = ss.insertSheet(name);
    const h = SCHEMA[name];
    if (s.getMaxColumns() < h.length) s.insertColumnsAfter(s.getMaxColumns(), h.length - s.getMaxColumns());
    const minRows = name === 'Buckets' ? 20000 : (name === 'Log' ? 30000 : 2000);
    if (s.getMaxRows() < minRows) s.insertRowsAfter(s.getMaxRows(), minRows - s.getMaxRows());
    s.getRange(1, 1, s.getMaxRows(), h.length).setNumberFormat('@');
    s.getRange(1, 1, 1, h.length).setValues([h]).setFontWeight('bold');
    s.setFrozenRows(1);
  });
  const def = ss.getSheetByName('Sheet1');
  if (def && def.getLastRow() === 0 && ss.getSheets().length > 1) ss.deleteSheet(def);

  if (!read_('Settings').length) append_('Settings', Object.keys(SETTINGS_SEED).map(k => ({ key: k, value: SETTINGS_SEED[k] })));
  if (!read_('Tehsils').length) append_('Tehsils', TEHSIL_SEED.map(r => obj_(SCHEMA.Tehsils, r)));
  if (!read_('Reasons').length) append_('Reasons', REASON_SEED.map(r => ({
    code: r[0], tier: r[1], label: r[2], report_label: r[3], checklist_col: r[4] || '', sort: r[5], active: 'Y' })));
  if (!read_('Users').length) {
    const id = 'U' + Date.now();
    append_('Users', [{ user_id: id, name: 'Pushpak', designation: 'Tehsildar', mobile: '', tehsil_id: '', role: 'ADMIN',
      pin_hash: hash_(id, SETTINGS_SEED.default_pin), active: 'Y', created_at: now_(), updated_at: now_() }]);
  }
  if (!read_('Villages').length) append_('Villages', ASSAR_VILLAGES.map(v => ({
    village_id: v[0], tehsil_id: 'T_ASSAR', name: v[1], portal_total: v[2], portal_claimed: v[3],
    portal_as_on: '2026-09-30', active: 'Y' })));

  ScriptApp.getProjectTriggers().forEach(t => { if (t.getHandlerFunction() === 'nightlyJob') ScriptApp.deleteTrigger(t); });
  ScriptApp.newTrigger('nightlyJob').timeBased().atHour(23).everyDays(1).inTimezone(TZ).create();
  Logger.log('Setup complete. Admin login: Pushpak / ' + SETTINGS_SEED.default_pin);
}

function selfTest() {
  const out = Object.keys(SCHEMA).map(n => n + ': ' + read_(n).length + ' rows');
  const admin = read_('Users').find(u => u.role === 'ADMIN');
  out.push('Admin login check: ' + (admin && admin.pin_hash === hash_(admin.user_id, setting_('default_pin')) ? 'OK' : 'FAILED'));
  out.push('Aadhaar checksum check: ' + (verhoeff_('234123412346') ? 'OK' : 'FAILED'));
  Logger.log(out.join('\n'));
}

