function setSetting_(k, v) {
  const rows = read_('Settings'), r = rows.find(x => x.key === k);
  if (r) { r.value = String(v); writeRows_('Settings', [r]); } else append_('Settings', [{ key: k, value: String(v) }]);
}

function ensureSheets_() {
  Object.keys(SCHEMA).forEach(name => {
    let s = ss_().getSheetByName(name);
    if (!s) s = ss_().insertSheet(name);
    const h = SCHEMA[name];
    if (s.getMaxColumns() < h.length) s.insertColumnsAfter(s.getMaxColumns(), h.length - s.getMaxColumns());
    s.getRange(1, 1, s.getMaxRows(), h.length).setNumberFormat('@');
    s.getRange(1, 1, 1, h.length).setValues([h]).setFontWeight('bold');
  });
}

function letterDefaults_(t) {
  return {
    letterhead: 'GOVERNMENT OF JAMMU AND KASHMIR\nOFFICE OF THE TEHSILDAR EXECUTIVE MAGISTRATE 1ST CLASS\nTEHSIL ' + String(t.name || '').toUpperCase() + ', DISTRICT DODA' +
      (t.tehsil_id === 'T_ASSAR' ? '\n(Email Id: tehsilassar1@gmail.com)' : ''),
    addressee: 'The Deputy Commissioner,\nDoda.',
    subject: 'Furnishing of information regarding Farmer ID Creation.',
    opening: 'Kindly refer to the subject cited above. In this regard the requisite information regarding creation of Farmer ID is as under:-',
    closing: 'Hence submitted.'
  };
}

/** Upgrades an existing database in place once. Safe to run any number of times. */
function migrate_() {
  if (DB.migrated) return;
  DB.migrated = true;
  if (setting_('schema_version') === SCHEMA_VERSION) return;
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    DB.cache = {};
    const ver = setting_('schema_version') || '1';
    if (ver === SCHEMA_VERSION) return;
    ensureSheets_(); DB.cache = {};
    if (Number(ver) < 2) migrateV2_();
    if (Number(ver) < 4) migrateV4_();
    if (Number(ver) < 6) migrateV6_();
    if (Number(ver) < 7) migrateV7_();
    if (Number(ver) < 8) migrateV8_();
    if (Number(ver) < 9) migrateV9_();
    if (Number(ver) < 10) migrateV10_();
    if (Number(ver) < 11) migrateV11_();
    if (Number(ver) < 5) { const all = read_('Buckets'); let ch = false; all.forEach(b => { if (b.status === 'NOT_SURVEYED') { const sg = suggest_(b.name, b.parentage); if (sg !== b.suggested_code) { b.suggested_code = sg; ch = true; } } }); if (ch) writeAll_('Buckets', all); }
    setSetting_('schema_version', SCHEMA_VERSION);
    CacheService.getScriptCache().put('dv', String(Date.now()), 21600);
  } finally { lock.releaseLock(); }
}

function migrateV2_() {
  {
    const reasons = read_('Reasons');
    const a06 = reasons.find(r => r.code === 'A06');
    if (a06) { a06.label = 'Shamlat deh (no individual owner)'; a06.report_label = 'Shamlat deh (no individual owner recorded)'; writeRows_('Reasons', [a06]); }
    if (!reasons.find(r => r.code === 'A12')) append_('Reasons', [{ code: 'A12', tier: 'A', label: 'Public use land (road, path, nallah, graveyard, abadi)',
      report_label: 'Public use land (road, path, nallah, graveyard, abadi)', checklist_col: '', sort: '6.5', active: 'Y' }]);
    read_('Tehsils').forEach(t => { const d = letterDefaults_(t); let ch = false; Object.keys(d).forEach(k => { if (!t[k]) { t[k] = d[k]; ch = true; } }); if (ch) writeRows_('Tehsils', [t]); });
    if (!read_('Settings').some(r => r.key === 'reminder_time')) setSetting_('reminder_time', SETTINGS_SEED.reminder_time);
    const all = read_('Buckets'); let changed = false;
    all.forEach(b => { if (b.status === 'NOT_SURVEYED') { const sg = suggest_(b.name, b.parentage); if (sg !== b.suggested_code) { b.suggested_code = sg; changed = true; } } });
    if (changed) writeAll_('Buckets', all);
    read_('Tehsils').filter(t => t.active === 'Y').forEach(t => ensurePractice_(t.tehsil_id, false));
  }
}

