function migrateV4_() {
  const now = now_();
  const reasons = read_('Reasons'); const ch = [];
  reasons.forEach(r => { const d = REASON_HI[r.code]; if (!d) return; if (!r.label_hi) r.label_hi = d[0]; if (!r.explain) r.explain = d[1]; if (!r.explain_hi) r.explain_hi = d[2]; ch.push(r); });
  if (ch.length) writeRows_('Reasons', ch);
  const vs = read_('Villages');
  const add = KASTIGARH_VILLAGES.filter(k => !vs.some(v => v.village_id === k[0])).map(k => ({ village_id: k[0], tehsil_id: 'T_KASTIGARH', name: k[1],
    portal_total: k[2], portal_claimed: k[3], portal_as_on: '2026-09-30', active: 'Y' }));
  if (add.length) append_('Villages', add);
  if (!read_('SummaryHistory').length) append_('SummaryHistory', read_('Villages').filter(v => v.practice !== 'Y' && v.portal_total !== '')
    .map(v => ({ date: v.portal_as_on || '2026-09-30', tehsil_id: v.tehsil_id, village_id: v.village_id, total: v.portal_total, claimed: v.portal_claimed, source: 'SETUP', entered_by: '', entered_at: now })));
  ['reg_start_date', 'list_fresh_days'].forEach(k => { if (!read_('Settings').some(r => r.key === k)) setSetting_(k, SETTINGS_SEED[k]); });
  const users = read_('Users'); const pin = setting_('default_pin');
  const ensureUser = (name, desig, role, tid, tehsils) => {
    const ex = users.find(x => x.active !== 'DEL' && String(x.name).toLowerCase() === name.toLowerCase() && (x.role === role || String(x.designation).indexOf(desig.split(' ')[0]) === 0));
    if (ex) { if (tehsils) { ex.tehsils = tehsils; ex.designation = desig; ex.role = role; ex.tehsil_id = tid; writeRows_('Users', [ex]); } return; }
    const id = 'U' + Utilities.getUuid().replace(/-/g, '').slice(0, 10);
    const o = { user_id: id, name: name, designation: desig, mobile: '', tehsil_id: tid, role: role, pin_hash: hash_(id, pin), active: 'Y', created_at: now, updated_at: now, tehsils: tehsils || '' };
    append_('Users', [o]);
  };
  ensureUser('Pankaj', 'Dealing Assistant', 'DA', 'T_ASSAR', '');
  ensureUser('Jasveer', 'Dealing Assistant', 'DA', 'T_KASTIGARH', '');
  ensureUser('Praban', 'Naib Tehsildar (Assar / Topneel)', 'NT', 'T_ASSAR', 'T_ASSAR,T_KASTIGARH');
  // Registered farmers loaded before coverage windows existed: record them as one file covering the start date to that upload.
  const farmers = read_('Farmers');
  if (farmers.length && !read_('RegFiles').length) {
    const byT = {}; farmers.forEach(f => { (byT[f.tehsil_id] = byT[f.tehsil_id] || []).push(f); });
    Object.keys(byT).forEach(t => {
      const at = read_('Villages').filter(v => v.tehsil_id === t && v.reg_uploaded_at).map(v => v.reg_uploaded_at).sort().pop() || now;
      const fid = 'R' + Utilities.getUuid().replace(/-/g, '').slice(0, 10);
      append_('RegFiles', [{ file_id: fid, tehsil_id: t, file_name: '(loaded before coverage tracking)', file_ts: '', downloaded_at: at, cov_from: setting_('reg_start_date'),
        cov_to: at.slice(0, 10), note: 'Migrated', uploaded_by: '', uploaded_at: at, rows: byT[t].length, farmers: byT[t].length, new: byT[t].length, newly_approved: 0, missing: 0 }]);
      byT[t].forEach(f => f.files = fid);
    });
    writeAll_('Farmers', farmers);
  }
  checkSharing_();
}

