  const uploads = read_('Uploads').filter(x => x.tehsil_id === tid).slice(-80).reverse()
    .map(x => ({ ts: x.ts, by: un[x.user_id] || '', village: vn[x.village_id] || x.village_id, kind: x.file_ts === 'REGISTERED' ? 'Registered farmers' : 'Bucket list',
      rows: x.rows, new: x.new, gone: x.gone, changed: x.changed }));
  const hist = {}; read_('SummaryHistory').filter(h => h.tehsil_id === tid).forEach(h => (hist[h.village_id] = hist[h.village_id] || []).push({ date: h.date, total: h.total, claimed: h.claimed, source: h.source }));
  const fs = read_('Farmers').filter(f => f.tehsil_id === tid);
