/** req: {tehsil_id, freeze} — everything the PDF needs. freeze:true stores the figures as the day's report snapshot. */
function reportData_(req, u) {
  const tehsilId = officeTehsil_(req, u, false);
  const st = computeStats_(tehsilId);
  const t = read_('Tehsils').find(x => x.tehsil_id === tehsilId) || {};
  const camps = read_('Camps').filter(c => c.tehsil_id === tehsilId && c.date === st.date).map(c => { const o = Object.assign({}, c); delete o._row; return o; });
  const reasons = read_('Reasons').map(r => { const o = Object.assign({}, r); delete o._row; return o; });
  if (req.freeze) {
    const lock = LockService.getScriptLock(); lock.waitLock(30000);
    try { append_('Snapshots', [{ date: st.date, tehsil_id: tehsilId, village_id: 'REPORT',
      data: JSON.stringify({ generated_at: now_(), by: u.user_id, villages: st.villages, totals: st.totals }) }]); }
    finally { lock.releaseLock(); }
  }
  return { stats: st, camps: camps, reasons: reasons,
    tehsil: { tehsil_id: tehsilId, name: t.name, report_title: t.report_title, signature: t.signature, footnote: t.footnote, letterhead: t.letterhead,
              addressee: t.addressee, subject: t.subject, opening: t.opening, closing: t.closing, last_ref: t.last_ref } };
}

/** req: {user_id} — removes a login. Past entries keep the person's name in the history. */
function deleteUser_(req, u) {
  const users = read_('Users'), x = users.find(y => y.user_id === req.user_id && y.active !== 'DEL');
  if (!x) throw new Error('Login not found.');
  if (x.user_id === u.user_id) throw new Error('You cannot delete your own login.');
  if (u.role !== 'ADMIN') { if (x.role === 'ADMIN' || x.role === 'DA') throw new Error('Only the Admin can delete this login.'); mustManage_(u, x.tehsil_id); }
  x.active = 'DEL'; x.updated_at = now_();
  writeRows_('Users', [x]);
  const asg = read_('Assignments'); let changed = false;
  asg.forEach(a => { if (a.user_id === x.user_id && a.active === 'Y') { a.active = 'N'; a.updated_at = now_(); changed = true; } });
  if (changed) writeAll_('Assignments', asg);
  read_('Villages').forEach(v => { if (v.patwari_user_id === x.user_id) { v.patwari_user_id = ''; writeRows_('Villages', [v]); } });
  writeAll_('Sessions', read_('Sessions').filter(s => s.user_id !== x.user_id));
  append_('Log', [{ ts: now_(), user_id: u.user_id, bucket_id: '', action: 'DELETE_USER', field: 'user', old_value: x.name + ' (' + x.designation + ')', new_value: '' }]);
  return {};
}

