/** Moves every village (and the "Patwari in reports" mark) from one person to another, e.g. on transfer. */
function transferVillages_(req, u) {
  const users = read_('Users'), from = users.find(x => x.user_id === req.from_user), to = users.find(x => x.user_id === req.to_user && x.active === 'Y');
  if (!from || !to) throw new Error('Choose both people.');
  const vm = {}; read_('Villages').forEach(v => vm[v.village_id] = v);
  const rows = read_('Assignments'), now = now_(); let n = 0;
  rows.filter(a => a.user_id === from.user_id && a.active === 'Y' && vm[a.village_id] && canManage_(u, vm[a.village_id].tehsil_id)).forEach(a => {
    a.active = 'N'; a.updated_at = now;
    const ex = rows.find(b => b.user_id === to.user_id && b.village_id === a.village_id);
    if (ex) { ex.active = 'Y'; ex.updated_at = now; } else rows.push({ user_id: to.user_id, village_id: a.village_id, share: a.share, active: 'Y', updated_at: now });
    n++;
  });
  writeAll_('Assignments', rows);
  const vs = read_('Villages').filter(v => v.patwari_user_id === from.user_id && canManage_(u, v.tehsil_id));
  vs.forEach(v => v.patwari_user_id = to.user_id); if (vs.length) writeRows_('Villages', vs);
  append_('Log', [{ ts: now, user_id: u.user_id, bucket_id: '', action: 'TRANSFER', field: 'villages', old_value: from.name, new_value: to.name + ' (' + n + ')' }]);
  return { moved: n };
}

