    const bc = T.by_code, cards = [];
    if (T.pending) cards.push({ n: T.pending, t: 'Farmer IDs pending approval on the portal', a: 'Approve them on the portal: no field work needed.' });
    if ((bc.A02 || 0) + (bc.A03 || 0)) cards.push({ n: (bc.A02 || 0) + (bc.A03 || 0), t: 'heirs of dead owners: inheritance mutation not done or not attested', a: 'Plan a mutation camp for these villages.' });
    if ((bc.B11 || 0) + (bc.B01 || 0) + (bc.B02 || 0)) cards.push({ n: (bc.B11 || 0) + (bc.B01 || 0) + (bc.B02 || 0), t: 'landholders: Aadhaar not linked to a mobile', a: 'Hold an Aadhaar–mobile linking camp with the bank or CSC.' });
    if (T.to_link) cards.push({ n: T.to_link, t: 'registered farmers not linked to their land entry', a: 'Field staff link them in "Link registered".' });
    cards.sort((x, y) => y.n - x.n);
