function migrateV7_() {
  const users = read_('Users'), now = now_();
  if (!read_('PHs').length) {
    const vs = read_('Villages'), ch = [];
    append_('PHs', PH_SEED.map((s, i) => {
      const pu = users.find(x => x.active !== 'DEL' && String(x.name).trim().toLowerCase() === s[2].toLowerCase() && userTehsils_(x).indexOf(s[0]) >= 0) ||
                 users.find(x => x.active !== 'DEL' && String(x.name).trim().toLowerCase() === s[2].toLowerCase());
      const id = 'PH' + (i + 1);
      s[3].forEach(lgd => { const v = vs.find(x => x.village_id === lgd); if (v) { v.ph_id = id; ch.push(v); } });
      return { ph_id: id, tehsil_id: s[0], name: s[1], patwari_user_id: pu ? pu.user_id : '', pending_names: s[4], sort: String(i + 1), active: 'Y' };
    }));
    if (ch.length) writeRows_('Villages', ch);
  }
  // Built-in list of registered farmers as on 05.10.2026 (both tehsils); later uploads add to it.
  const vmap = {}; read_('Villages').forEach(v => vmap[v.village_id] = v);
  const farmers = read_('Farmers'), fmap = {}; farmers.forEach(f => { f.missing = ''; fmap[f.farmer_id] = f; });
  const fileIds = {}, today = today_();
  BASELINE_FARMERS_0510.split('\n').forEach(line => {
    const r = line.split('|'), v = vmap[r[10]]; if (!r[0] && r[1]) r[0] = 'E:' + r[1]; if (!r[0] || !v) return;
    if (!fileIds[v.tehsil_id]) fileIds[v.tehsil_id] = 'R0510' + v.tehsil_id;
    let o = fmap[r[0]];
    if (!o) { o = {}; SCHEMA.Farmers.forEach(k => o[k] = ''); o.farmer_id = r[0]; o.first_seen = '2026-10-05'; farmers.push(o); fmap[r[0]] = o; }
    Object.assign(o, { enrollment_no: r[1], village_id: r[10], tehsil_id: v.tehsil_id, name: r[2], gender: r[3], age: r[4], category: r[5],
      status: String(r[6]).toUpperCase() === 'APPROVED' ? 'APPROVED' : 'PENDING', inserted_by: r[7], mobile: String(r[8]).replace(/\D/g, '').slice(-10),
      aadhaar_mask: r[9], name_score: r[11], last_seen: today, missing: '' });
    const fl = String(o.files || '').split(',').filter(Boolean); if (fl.indexOf(fileIds[v.tehsil_id]) < 0) fl.push(fileIds[v.tehsil_id]); o.files = fl.join(',');
  });
  const buckets = read_('Buckets'), logs = [], admin = users.find(x => x.role === 'ADMIN') || { user_id: '' };
  Object.keys(fileIds).forEach(t => {
    farmers.forEach(f => { if (f.tehsil_id === t && !f.bucket_id && f.link_conf !== 'NONE') f.link_conf = ''; });
    linkFarmers_(t, farmers, buckets, admin, true, logs);
  });
  writeAll_('Farmers', farmers); writeAll_('Buckets', buckets); if (logs.length) append_('Log', logs);
  append_('RegFiles', Object.keys(fileIds).map(t => ({ file_id: fileIds[t], tehsil_id: t, file_name: 'Built-in list as on 05.10.2026', file_ts: '', downloaded_at: '2026-10-05 16:39:00',
    cov_from: '2026-08-02', cov_to: '2026-10-05', note: 'Built in', uploaded_by: '', uploaded_at: now, rows: farmers.filter(f => f.tehsil_id === t).length,
    farmers: farmers.filter(f => f.tehsil_id === t).length, new: 0, newly_approved: 0, missing: 0 })));
}

/** Everything the home screen needs, in one request. */
function home_(req, u) {
  const out = { checklist: null, status: {} };
  if (!isField_(u)) out.checklist = cached_('ck:' + u.user_id, 120, () => checklist_({}, u));
  userTehsils_(u).forEach(t => { try { out.status[t] = phStatus_({ tehsil_id: t }, u); } catch (e) {} });
  return out;
}

