  const bVil = {}; read_('Buckets').forEach(b => { if (b.tehsil_id === tid) bVil[b.bucket_id] = b.village_id; });
  const fs = read_('Farmers').filter(f => f.tehsil_id === tid && f.first_seen === date && f.status !== 'REJECTED' && f.missing !== 'Y')
