  fs.forEach(f => { const k = f.aadhaar || ('F:' + f.farmer_id); if (seenA[k]) dups.push({ name: f.name, village: vn[f.village_id] || f.village_id, other: seenA[k] }); else { seenA[k] = f.name; list.push(f); } });
  const dm = deployMap_(tid, date), per = {}, vil = {};
