    const moves = officials.filter(o => o.village_ids.length && o.pool < 15).map(o => { const to = room.find(r => o.village_ids.indexOf(r.vid) < 0 && pool[r.vid] >= 40); return to ? { user_id: o.user_id, name: o.name, from: o.villages, to_id: to.vid, to: vn[to.vid], pool: pool[to.vid] } : null; }).filter(Boolean);
    const closes = read_('Snapshots').filter(x => x.tehsil_id === tid && x.village_id === 'CLOSE' && x.date < today).map(x => { try { return JSON.parse(x.data); } catch (e) { return null; } }).filter(Boolean);
    const missedBefore = {}; closes.forEach(cl => Object.keys(cl.users || {}).forEach(uid => { if (cl.users[uid] < (cl.floor || floor)) missedBefore[uid] = (missedBefore[uid] || 0) + 1; }));
    const closed = !!last && last.slice(11, 16) >= String(s.day_close || '17:00');
