      sorting: sortingStatus_(tid), pace: (() => { const vp = villagePace_(tid, c, today); return vp; })(), top2: officials.filter(o => o.today > 0).slice(0, 2).map(o => ({ name: o.name, today: o.today, villages: o.villages })),
