/** Village figures for the live views: today, target, projection at 5 PM, the people, and what blocks it. */
function villagePace_(tid, c, today) {
  const s = settings_(), floor = Number(s.official_floor || 50), nowM = minutesOf_(now_());
  const users = {}; read_('Users').forEach(x => users[x.user_id] = x);
  const phs = read_('PHs').filter(p => p.tehsil_id === tid), asg = read_('Assignments').filter(a => a.active === 'Y');
  const tier = {}, rl = {}; read_('Reasons').forEach(r => { tier[r.code] = r.tier; rl[r.code] = r.report_label || r.label; });
  const by = {}; read_('Buckets').forEach(b => { if (b.tehsil_id !== tid || b.status === 'CLAIMED') return; const x = by[b.village_id] = by[b.village_id] || { codes: {}, notsorted: 0 };
    if (b.status === 'NOT_SURVEYED') x.notsorted++; else x.codes[b.reason_code] = (x.codes[b.reason_code] || 0) + 1; });
  const ACT = { B11: 'Aadhaar–mobile linking camp', B01: 'Aadhaar–mobile linking camp', B02: 'Aadhaar–mobile linking camp (doorstep)', A02: 'Mutation list to the Patwari', B04: 'Call them: family at the camp relays the OTPs', B03: 'Call them: family relays the OTPs', C01: 'Call them to the camp: ready now', C03: 'Visit: possible, not yet checked' };
  const start = 9 * 60, end = minutesOf_(today + ' ' + (s.day_close || '17:00') + ':00'), span = Math.max(60, end - start), done = Math.min(span, Math.max(30, nowM - start));
  return read_('Villages').filter(v => v.tehsil_id === tid && v.active === 'Y' && v.practice !== 'Y' && !isCollect_(v) && (v.first_upload_date || Number(v.portal_total) > 0)).map(v => {
    const ops = asg.filter(a => a.village_id === v.village_id && users[a.user_id] && users[a.user_id].active === 'Y');
    const target = villageTarget_(v, ops.length, floor), ids = (c.vil[v.village_id] || {}).ids || 0;
    const proj = nowM >= end ? ids : Math.round(ids * span / done), pw = patwariOf_(v, phs, users), inc = users[v.incharge_user_id];
    const x = by[v.village_id] || { codes: {}, notsorted: 0 };
    const top = Object.keys(x.codes).filter(k => tier[k] !== 'A').sort((a, b) => x.codes[b] - x.codes[a])[0];
    const block = x.notsorted > 50 ? { n: x.notsorted, text: 'Not sorted yet', act: 'Patwari to sort this evening' } : top ? { n: x.codes[top], text: rl[top] || top, act: ACT[top] || '' } : null;
    return { village_id: v.village_id, name: v.name, ids, target, proj, behind: target > 0 && proj < target, below: target > 0 && ids < target,
      incharge: inc ? { user_id: inc.user_id, name: inc.name, mobile: inc.mobile || '' } : null, patwari: pw ? { user_id: pw.user_id, name: pw.name, mobile: pw.mobile || '' } : null,
      operators: ops.map(a => users[a.user_id].name), block };
  });
}
/** Officials above the minimum 3 closes in a row; the tehsil's forecast to the deadline. */
function streaks_(tid, floor) {
  const closes = read_('Snapshots').filter(x => x.tehsil_id === tid && x.village_id === 'CLOSE').sort((a, b) => a.date < b.date ? -1 : 1).map(x => { try { return JSON.parse(x.data); } catch (e) { return null; } }).filter(Boolean).slice(-3);
  if (closes.length < 3) return [];
  const un = {}; read_('Users').forEach(x => un[x.user_id] = x.name);
  return Object.keys(closes[2].users || {}).filter(uid => closes.every(cl => (cl.users || {})[uid] >= (cl.floor || floor))).map(uid => un[uid] || '').filter(Boolean);
}
function forecast_(tid) {
  const s = settings_(), today = today_(), fs = read_('Farmers').filter(f => f.tehsil_id === tid && f.missing !== 'Y' && f.status !== 'REJECTED');
  const wk = addDays_(today, -7), lastWeek = fs.filter(f => f.first_seen >= wk && f.first_seen < today).length, pace = Math.round(lastWeek / 7);
  const left = Math.max(0, daysBetween_(today, s.final_deadline) + 1), st = computeStats_(tid), total = st.totals.total, made = st.totals.claimed;
  return { deadline: s.final_deadline, days_left: left, pace, expected: made + pace * left, total, made, needed: left ? Math.ceil(Math.max(0, total - made) / left) : 0 };
}
/** The week's best (Friday certificates): top operator and top In-charge of each tehsil, from the daily closes. */
function weekTop_(req, u) {
  if (['ADMIN', 'DA', 'NT'].indexOf(u.role) < 0) throw new Error('Not allowed.');
  const today = today_(), d = new Date(today + 'T12:00:00Z'), mon = addDays_(today, -((d.getUTCDay() + 6) % 7));
  const un = {}; read_('Users').forEach(x => un[x.user_id] = x);
  return { from: mon, to: today, tehsils: userTehsils_(u).map(tid => {
    const closes = read_('Snapshots').filter(x => x.tehsil_id === tid && x.village_id === 'CLOSE' && x.date >= mon).map(x => { try { return JSON.parse(x.data); } catch (e) { return null; } }).filter(Boolean);
    const op = {}, vil = {};
    closes.forEach(cl => { Object.keys(cl.users || {}).forEach(uid => op[uid] = (op[uid] || 0) + cl.users[uid]); Object.keys(cl.villages || {}).forEach(vid => { const x = vil[vid] = vil[vid] || { ids: 0, target: 0, inc: cl.villages[vid].incharge }; x.ids += cl.villages[vid].ids; x.target += cl.villages[vid].target; if (cl.villages[vid].incharge) x.inc = cl.villages[vid].incharge; }); });
    const topOp = Object.keys(op).sort((a, b) => op[b] - op[a])[0];
    const inc = {}; Object.keys(vil).forEach(vid => { const x = vil[vid]; if (!x.inc || !x.target) return; const y = inc[x.inc] = inc[x.inc] || { ids: 0, target: 0, villages: [] }; y.ids += x.ids; y.target += x.target; y.villages.push(vid); });
    const topInc = Object.keys(inc).sort((a, b) => inc[b].ids / inc[b].target - inc[a].ids / inc[a].target)[0];
    const vn = {}; read_('Villages').forEach(v => vn[v.village_id] = v.name);
    return { tehsil_id: tid, name: tehsilName_(tid), days: closes.length,
      operator: topOp ? { name: un[topOp] ? un[topOp].name : '', designation: un[topOp] ? un[topOp].designation : '', ids: Math.round(op[topOp]) } : null,
      incharge: topInc ? { name: un[topInc] ? un[topInc].name : '', designation: un[topInc] ? un[topInc].designation : '', ids: inc[topInc].ids, target: inc[topInc].target, villages: inc[topInc].villages.map(v => vn[v] || v) } : null };
  }) };
}
/** One official's record: today, last 7 closes, villages, calls logged, days below the minimum. */
function official_(req, u) {
  if (['ADMIN', 'DA', 'NT'].indexOf(u.role) < 0 && req.user_id !== u.user_id) throw new Error('Not allowed.');
  const x = read_('Users').find(y => y.user_id === req.user_id); if (!x) throw new Error('Official not found.');
  const tid = x.tehsil_id || userTehsils_(x)[0], floor = Number(setting_('official_floor') || 50);
  const closes = read_('Snapshots').filter(s2 => s2.tehsil_id === tid && s2.village_id === 'CLOSE').sort((a, b) => a.date < b.date ? -1 : 1).slice(-7)
    .map(s2 => { let d = {}; try { d = JSON.parse(s2.data); } catch (e) {} return { date: s2.date, ids: (d.users || {})[x.user_id], floor: d.floor || floor }; }).filter(r => r.ids !== undefined);
  const vn = {}; read_('Villages').forEach(v => vn[v.village_id] = v);
  const p = pulseTehsil_(tid), me = p.officials.find(o => o.user_id === x.user_id);
  return { user: publicUser_(x), today: me ? me.today : 0, villages: assignedVillageIds_(x).map(v => (vn[v] || {}).name || v),
    incharge_of: read_('Villages').filter(v => v.incharge_user_id === x.user_id).map(v => v.name), patwari_of: phVillageIds_(x).map(v => (vn[v] || {}).name || v),
    days: closes, below_days: closes.filter(r => r.ids < r.floor).length,
    calls: read_('SupLog').filter(s2 => s2.user_id === x.user_id).slice(-10).map(s2 => ({ at: s2.at, note: s2.note })) };
}
function migrateV11_() {
  if (!read_('Settings').some(r => r.key === 'designations')) setSetting_('designations', JSON.stringify(DESIGNATIONS));
  // the Patwari now comes from the halqa; a Patwari named on the village becomes its In-charge if none is set
  const vs = read_('Villages'), ch = []; vs.forEach(v => { if (!v.incharge_user_id && v.patwari_user_id) { v.incharge_user_id = v.patwari_user_id; ch.push(v); } }); if (ch.length) writeRows_('Villages', ch);
}

/* ============================== START FRESH ============================== */

/** Clears every field entry (test or otherwise) but keeps uploaded files, figures, staff and settings; then re-runs automatic matching. */
function startFresh_(req, u) {
  if (u.role !== 'ADMIN') throw new Error('Only the Admin can start fresh.');
  if (req.confirm !== 'RESET') throw new Error('Type RESET to confirm.');
  const all = read_('Buckets');
  all.forEach(b => {
    if (String(b.village_id).indexOf('P_') === 0) return;
    const gone = b.portal_state === 'GONE';
    Object.assign(b, { reason_code: '', residence: '', current_location: '', aadhaar: '', mobile: '', farmer_id: '', remarks: '', dup_group: '', dup_conf: '',
      dup_confirmed: '', dup_role: '', flag: '', surveyed_date: '', surveyed_by: '', updated_by: '', updated_at: '', claimed_by: '' });
    if (gone) { b.status = 'CLAIMED'; b.claimed_source = 'PORTAL'; } else { b.status = 'NOT_SURVEYED'; b.claimed_source = ''; b.claimed_date = ''; }
    b.suggested_code = suggest_(b.name, b.parentage);
    if (b.gender_source === 'USER' || !b.gender_source) { b.gender = b.suggested_code ? '' : gender_(b.name); b.gender_source = b.suggested_code ? '' : 'AUTO'; }
  });
  const farmers = read_('Farmers');
  farmers.forEach(f => Object.assign(f, { bucket_id: '', link_method: '', link_conf: '', candidates: '', linked_by: '', linked_at: '' }));
  const tehsils = read_('Tehsils').filter(t => t.active === 'Y').map(t => t.tehsil_id), logs = [];
  let auto = 0;
  tehsils.forEach(t => { detectDups_(t, all); auto += linkFarmers_(t, farmers, all, u, true, logs).auto; });
  writeAll_('Buckets', all);
  writeAll_('Farmers', farmers);
  writeAll_('Camps', []);
  const old = read_('Log').map(l => { const o = Object.assign({}, l); delete o._row; return o; });
  if (old.length) append_('LogArchive', old);
  writeAll_('Log', logs);
  tehsils.forEach(t => ensurePractice_(t, true));
  return { entries: all.filter(b => String(b.village_id).indexOf('P_') !== 0).length, farmers: farmers.length, auto_linked: auto };
}
function startFreshFromEditor() {
  const admin = read_('Users').find(x => x.role === 'ADMIN' && x.active === 'Y');
  Logger.log(JSON.stringify(startFresh_({ confirm: 'RESET' }, admin)));
}

/* ============================== NIGHTLY JOB ============================== */

/** 11 PM daily: stats snapshot for trends + backup copy of the database. */
function nightlyJob() {
  const date = today_();
  const snaps = [];
  read_('Tehsils').filter(t => t.active === 'Y').forEach(t => {
    const st = computeStats_(t.tehsil_id, date);
    st.villages.forEach(v => snaps.push({ date: date, tehsil_id: t.tehsil_id, village_id: v.village_id, data: JSON.stringify(v) }));
    snaps.push({ date: date, tehsil_id: t.tehsil_id, village_id: 'TOTAL', data: JSON.stringify(st.totals) });
  });
  const kept = read_('Snapshots').filter(s => s.date !== date || s.village_id === 'REPORT');
  writeAll_('Snapshots', kept.concat(snaps));

  const name = 'FarmerID Backups';
  const it = DriveApp.getFoldersByName(name);
  const folder = it.hasNext() ? it.next() : DriveApp.createFolder(name);
  const bf = driveFolder_(['Backups']); DriveApp.getFileById(ss_().getId()).makeCopy('FarmerID DB backup ' + date, bf);
  const oldB = []; const it2 = bf.getFiles(); while (it2.hasNext()) { const x = it2.next(); if (x.getDateCreated() < new Date(Date.now() - 31 * 86400000)) oldB.push(x); } oldB.forEach(x => x.setTrashed(true));
  if (setting_('practice_keep') !== date) read_('Tehsils').filter(t => t.active === 'Y').forEach(t => { try { ensurePractice_(t.tehsil_id, true); } catch (e) {} });
  pinExpire_();
  if (new Date(date + 'T12:00:00Z').getUTCDay() === 0) { try { weeklyExcel_(); } catch (e) {} }
  const cutoff = addDays_(date, -30), logs = read_('Log');
  const old = logs.filter(l => String(l.ts).slice(0, 10) < cutoff);
  if (old.length) { append_('LogArchive', old.map(l => { const o = Object.assign({}, l); delete o._row; return o; })); writeAll_('Log', logs.filter(l => String(l.ts).slice(0, 10) >= cutoff)); }
  checkSharing_();
}

